style.css:
/* 将主要背景设置为护眼绿（豆沙绿） */
body, html {
    background-color: #C7EDCC !important;
    color: #000000 !important; /* 可选：修改文本颜色以保证可读性 */
}

/* 针对常见网页布局的容器元素 */
div, section, article, main, aside, footer, header, nav {
    background-color: #C7EDCC !important;
}

/* 针对一些特定的输入框和按钮 */
input, textarea, select, button {
    background-color: #C7EDCC !important;
    color: #000000 !important; /* 保证可读性 */
}

/* 覆盖常见的网页块状元素 */
p, span, table, td, th, ul, ol, li {
    background-color: #C7EDCC !important;
}

/* 确保特殊框架和嵌套内容的背景也更改 */
iframe, embed, object {
    background-color: #C7EDCC !important;
}
